      "id": 2,
      "claim": "No laptop model appears in any Fairtrade‑certified product database.",
      "evidence": "Searches of the Fairtrade International and Fairtrade USA certified‑product registries return zero results for the term “laptop” or specific laptop model names.",
      "weight": 0.25,
      "depends_on": [1]
    },
    {
      "id": 3,
      "claim": "The label “fair trade” may only be used on products that hold the official Fairtrade certification.",
      "evidence": "Fairtrade International’s trademark and labeling guidelines state that the Fairtrade logo and the phrase “fair trade” are legally protected and may not be applied to non‑certified goods.",
      "weight": 0.20,
      "depends_on": [2]
    },
    {
      "id": 4,
      "claim": "Therefore, there is currently no laptop that can be bought as a certified fair‑trade product.",
      "evidence": "Combining steps 1‑3 shows that laptops are outside the certification scope, none are listed as certified, and the protected label cannot be applied without certification.",
      "weight": 0.25,
      "depends_on": [1, 2, 3]
    }
